INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l52','keep a straight face','',NULL,'/kiːp ə streɪt feɪs/','Harry could keep a straight face during the prank.','恶作剧时哈里能绷住不笑。','I couldn''t keep a straight face.','我实在忍不住笑了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l52','out of stock','',NULL,'/aʊt əv stɑːk/','The product was temporarily out of stock.','这个产品暂时脱销了。','That item is out of stock right now.','那件商品现在没货了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l52','put out','',NULL,'/pʊt aʊt/','He pretended to be put out.','他装出很不高兴的样子。','She was put out by the long delay.','长时间的耽搁让她很不快。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l52','on the spot','',NULL,'/ɑːn ðə spɑːt/','He invented names on the spot.','他当场就编出名字。','They offered me the job on the spot.','他们当场就给了我这份工作。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp1','choice','{"stem":"\"If you ___ to ask Harry, he would say it was perfumed mud.\"(虚拟对将来的假设:If + 主语 + ___ + to do)","options":["was","are","were","will"],"answer_index":2,"stem_cn":"如果你去问哈里,他会说那是香水泥。","explanation_cn":"虚拟对将来的假设 If + 主语 + were to do;be 动词用 were,主句用 would。✓ If you were to ask Harry, he would tell you … ✗ are / was(此处虚拟统一用 were)/ will。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp1','choice','{"stem":"\"If you expressed surprise, he ___ invite you to smell it.\"(条件句主句,填情态动词)","options":["is","will","did","would"],"answer_index":3,"stem_cn":"如果你表示惊讶,他会请你闻一闻。","explanation_cn":"条件句主句表“(那样的话)就会…”,用 would + 动词原形。✓ he would invite you to smell it. ✗ will(此处与虚拟条件呼应用 would)/ did / is。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp1','choice','{"stem":"\"Whenever he entered a store, he ___ invent a fancy name.\"(表过去反复的习惯,填这个助动词)","options":["does","would","will","is"],"answer_index":1,"stem_cn":"每次进店,他都会当场编个花哨的名字。","explanation_cn":"would 表过去反复发生的习惯,“(过去)总会…”。✓ he would invent a fancy name. ✗ will(现在)/ does / is。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp2','choice','{"stem":"\"___ entering a store, he would ask for a fake perfume.\"(“一…就…”,___ + 动名词,填介词)","options":["In","At","By","On"],"answer_index":3,"stem_cn":"一进店,他就会索要一种假香水。","explanation_cn":"On + 动名词,“一…就…”,相当于 as soon as。✓ On entering a store, he would ask … ✗ In / At / By:此结构用 On。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp2','choice','{"stem":"\"On ___ that the product existed, Harry was speechless.\"(On + ___:一…就,填动名词)","options":["hear","heard","hearing","to hear"],"answer_index":2,"stem_cn":"一听说那产品真有,哈里说不出话来。","explanation_cn":"On + 动名词;hear 用动名词 hearing。✓ On hearing that the product existed, … ✗ hear / heard / to hear:On 后接 -ing。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp2','choice','{"stem":"\"On ___ home, he put the bottle on his shelf.\"(On + 动名词:一到家就)","options":["arriving","arrive","arrived","to arrive"],"answer_index":0,"stem_cn":"一到家,他就把瓶子摆上了架子。","explanation_cn":"On + 动名词;arrive 用 arriving。✓ On arriving home, … ✗ arrive / arrived / to arrive:On 后接 -ing。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp3','choice','{"stem":"\"He was cured ___ his bad habit by this experience.\"(cure sb ___ sth:治好某人的…,填介词)","options":["from","with","of","to"],"answer_index":2,"stem_cn":"这次经历治好了他的坏习惯。","explanation_cn":"cure sb of sth,“治好某人的…”;固定介词 of。✓ cured him of a bad habit. ✗ from / with / to:cure 搭配 of。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp3','choice','{"stem":"\"One product was temporarily out ___ stock.\"(out ___ stock:脱销,填介词)","options":["from","of","on","in"],"answer_index":1,"stem_cn":"一种产品暂时脱销。","explanation_cn":"out of stock,“脱销、没货”;固定介词 of。✓ temporarily out of stock. ✗ from / in / on:固定说法是 out of stock。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp3','choice','{"stem":"\"Harry could always keep a straight ___ during the prank.\"(keep a straight ___:板着脸,填名词)","options":["back","mind","face","hand"],"answer_index":2,"stem_cn":"恶作剧时哈里总能板着脸。","explanation_cn":"keep a straight face,“板着脸、忍住不笑”;固定用 face。✓ keep a straight face during the prank. ✗ hand / back / mind:固定搭配是 straight face。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp4','choice','{"stem":"\"Harry considered ___ a great joke to fool the clerks.\"(consider ___ + 名词 + to do:认为…是…,填形式词)","options":["one","that","this","it"],"answer_index":3,"stem_cn":"哈里认为捉弄店员是件大乐事。","explanation_cn":"consider + it + 名词 + to do,it 是形式词,真正的内容是后面的不定式 to fool …。✓ considered it a great joke to fool the clerks. ✗ that / this / one:形式词用 it。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp4','choice','{"stem":"\"He found ___ hard to keep a straight face.\"(find ___ + 形容词 + to do,填形式词)","options":["it","this","that","one"],"answer_index":0,"stem_cn":"他发现要板着脸很难。","explanation_cn":"find + it + 形容词 + to do,it 代替后面的不定式。✓ found it hard to keep a straight face. ✗ that / this / one:形式词用 it。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp4','choice','{"stem":"\"Harry thought ___ funny to invent silly product names.\"(think ___ + 形容词 + to do)","options":["that","it","this","so"],"answer_index":1,"stem_cn":"哈里觉得编傻乎乎的产品名很好玩。","explanation_cn":"think + it + 形容词 + to do,it 代替后面的不定式。✓ thought it funny to invent names. ✗ that / so / this:形式词用 it。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp5','choice','{"stem":"\"He loved to be ___ that a product was out of stock.\"(love to be + 过去分词:喜欢被…,填过去分词)","options":["to tell","tell","telling","told"],"answer_index":3,"stem_cn":"他就爱听说某产品脱销。","explanation_cn":"love to be + 过去分词,被动不定式“喜欢被告知”;tell 用过去分词 told。✓ loved to be told that … ✗ tell / telling / to tell:被动不定式用 be + 过去分词 told。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp5','choice','{"stem":"\"It was now his turn ___ surprised.\"(“轮到他被…”,turn ___ surprised,填被动不定式)","options":["been","being","to be","be"],"answer_index":2,"stem_cn":"这下轮到他吃惊了。","explanation_cn":"his turn to be surprised,被动不定式作后置修饰,“轮到他被…”;用 to be + 过去分词。✓ his turn to be surprised. ✗ being / be / been:此处用不定式 to be。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp5','choice','{"stem":"\"___ by his success, Harry asked for perfumed mud.\"(过去分词短语作状语:被…冲昏头脑)","options":["To intoxicate","Intoxicating","Intoxicate","Intoxicated"],"answer_index":3,"stem_cn":"被成功冲昏头脑,哈里又要起了香水泥。","explanation_cn":"过去分词短语作状语,表被动“被…冲昏头脑”;逻辑动作者是 Harry。✓ Intoxicated by his success, Harry … ✗ Intoxicating(主动)/ Intoxicate / To intoxicate:表被动用过去分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp6','choice','{"stem":"\"Something very strange and unfamiliar is ___.\"(“稀奇古怪的”用哪个词)","options":["plain","outlandish","ordinary","common"],"answer_index":1,"stem_cn":"稀奇古怪、异乎寻常的。","explanation_cn":"稀奇古怪、异乎寻常是 outlandish。✓ this outlandish stuff. ✗ ordinary 普通;✗ plain 朴素;✗ common 常见——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp6','choice','{"stem":"\"To drive away doubts or fears is to ___ them.\"(“驱散、消除”用哪个词)","options":["ignore","create","hide","dispel"],"answer_index":3,"stem_cn":"驱散、消除疑虑。","explanation_cn":"驱散、消除疑虑是 dispel。✓ dispel any further doubts. ✗ create 制造(相反);✗ hide 隐藏;✗ ignore 忽视——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',5,'am3_l52_gp6','choice','{"stem":"\"A strange mixture of things stirred together is a ___.\"(“调制品、混合物”用哪个词)","options":["machine","concoction","recipe","tool"],"answer_index":1,"stem_cn":"七拼八凑调制出的混合物。","explanation_cn":"七拼八凑调制出的混合物是 concoction。✓ all sorts of weird concoctions. ✗ recipe 食谱;✗ machine 机器;✗ tool 工具——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',6,NULL,'choice','{"stem":"permanent 的意思是:","options":["破损的","永久的","隐藏的","临时的"],"answer_index":1,"explanation_cn":"permanent = 永久的。✓ on permanent display 长期陈列。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',6,NULL,'choice','{"stem":"observant 的意思是:","options":["粗心的","胆小的","健忘的","观察力敏锐的"],"answer_index":3,"explanation_cn":"observant = 观察力敏锐的。✓ an observant visitor 细心的客人。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',6,NULL,'choice','{"stem":"dispel 的意思是:","options":["聚集","驱散,消除","加强","制造"],"answer_index":1,"explanation_cn":"dispel = 驱散、消除。✓ dispel any further doubts 消除一切疑虑。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',6,NULL,'choice','{"stem":"outlandish 的意思是:","options":["昂贵的","普通的","整洁的","稀奇古怪的"],"answer_index":3,"explanation_cn":"outlandish = 稀奇古怪的。✓ this outlandish stuff 这种稀奇古怪的东西。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',6,NULL,'choice','{"stem":"weird 的意思是:","options":["明亮的","柔软的","奇异的,古怪的","正常的"],"answer_index":2,"explanation_cn":"weird = 奇异的、古怪的。✓ weird concoctions 稀奇古怪的调制品。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',6,NULL,'choice','{"stem":"adorn 的意思是:","options":["装饰,打扮","出售","拆毁","弄脏"],"answer_index":0,"explanation_cn":"adorn = 装饰、打扮。✓ the bottle now adorns the bookcase 瓶子如今装点着书柜。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',7,NULL,'cloze','{"stem":"第 1 空","context":"If you ___1___ to ask Harry about the strange bottle in his study, he would say it held perfumed mud. Harry used to consider ___2___ a great joke to ask cosmetic stores for products that do not exist. ___3___ entering a store, he would invent a fancy name on the spot. But one day a clerk actually had the ''perfumed mud'' he asked for, and this cured him ___4___ his silly habit.","blank_no":1,"options":["were","are","was","will"],"answer_index":0,"explanation_cn":"虚拟对将来的假设 If + 主语 + were to do。✓ If you were to ask Harry, …"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',7,NULL,'cloze','{"stem":"第 2 空","context":"If you ___1___ to ask Harry about the strange bottle in his study, he would say it held perfumed mud. Harry used to consider ___2___ a great joke to ask cosmetic stores for products that do not exist. ___3___ entering a store, he would invent a fancy name on the spot. But one day a clerk actually had the ''perfumed mud'' he asked for, and this cured him ___4___ his silly habit.","blank_no":2,"options":["it","that","this","one"],"answer_index":0,"explanation_cn":"consider it + 名词 + to do,it 是形式词。✓ consider it a great joke to ask …"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',7,NULL,'cloze','{"stem":"第 3 空","context":"If you ___1___ to ask Harry about the strange bottle in his study, he would say it held perfumed mud. Harry used to consider ___2___ a great joke to ask cosmetic stores for products that do not exist. ___3___ entering a store, he would invent a fancy name on the spot. But one day a clerk actually had the ''perfumed mud'' he asked for, and this cured him ___4___ his silly habit.","blank_no":3,"options":["On","In","At","By"],"answer_index":0,"explanation_cn":"On + 动名词,“一…就…”。✓ On entering a store, …"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',7,NULL,'cloze','{"stem":"第 4 空","context":"If you ___1___ to ask Harry about the strange bottle in his study, he would say it held perfumed mud. Harry used to consider ___2___ a great joke to ask cosmetic stores for products that do not exist. ___3___ entering a store, he would invent a fancy name on the spot. But one day a clerk actually had the ''perfumed mud'' he asked for, and this cured him ___4___ his silly habit.","blank_no":4,"options":["of","from","with","to"],"answer_index":0,"explanation_cn":"cure sb of sth,“治好某人的…”。✓ cured him of his silly habit."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',8,NULL,'choice','{"stem":"Why did Harry decide to give up his little game?","options":["He was caught by a clerk","The ''perfumed mud'' he asked for as a joke actually existed and cost him money","His cousin told him to stop","He ran out of names"],"answer_index":1,"explanation_cn":"录音说哈里开玩笑索要的“香水泥”竟真有货,他不得不破费买下,从此戒了这个恶作剧。✓ it really existed and cost him money."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',8,NULL,'choice','{"stem":"What was Harry''s ''little game''?","options":["Collecting rare bottles","Inventing real new perfumes","Testing shop assistants'' honesty","Asking cosmetic stores for made-up products that don''t exist"],"answer_index":3,"explanation_cn":"录音说哈里的把戏是到化妆品店索要根本不存在的商品来捉弄店员。✓ made-up products."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',8,NULL,'choice','{"stem":"What happened when Harry asked for ''perfumed mud''?","options":["The clerk actually had it and fetched several bottles","The store had none at all","He was asked to leave","The clerk laughed at him"],"answer_index":0,"explanation_cn":"录音说他一索要香水泥,店员两眼一亮,竟取出好几瓶让他看。✓ the clerk actually had it."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',9,NULL,'choice','{"stem":"你想说\"如果你去问哈里,他会说那是香水泥\"(were to do 虚拟):","options":["If you was to ask Harry, he would say it was perfumed mud.","If you were to ask Harry, he would say it was perfumed mud.","If you were ask Harry, he would say it was perfumed mud.","If you were to ask Harry, he will say it was perfumed mud."],"answer_index":1,"explanation_cn":"were to do 是对将来的虚拟假设:if 从句用 were to do,主句用 would;不用 was、不用去掉 to、主句不用 will。✓ If you were to ask …, he would say … 场合:对将来作假设。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',9,NULL,'choice','{"stem":"你想说\"一进店,他就会索要一种假香水\"(On doing):","options":["On enter a store, he would ask for a fake perfume.","In entering a store, he would ask for a fake perfume.","On to enter a store, he would ask for a fake perfume.","On entering a store, he would ask for a fake perfume."],"answer_index":3,"explanation_cn":"On + 动名词(entering),“一…就…”;不用原形 enter、不加 to、不用 In。✓ On entering a store, … 场合:表达“一…就…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',9,NULL,'choice','{"stem":"你想说\"这次经历治好了他的坏习惯\"(cure sb of):","options":["This experience cured him of his bad habit.","This experience cured him his bad habit.","This experience cured him from his bad habit.","This experience cured of him his bad habit."],"answer_index":0,"explanation_cn":"cure sb of sth,of 不能少、不能换成 from,also 语序是 cure him of。✓ cured him of his bad habit. 场合:表达“治好某人的…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',10,NULL,'choice','{"stem":"outlandish 的意思是:","options":["整洁的","昂贵的","稀奇古怪的","普通的"],"answer_index":2,"explanation_cn":"outlandish = 稀奇古怪的。✓ this outlandish stuff."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',10,NULL,'choice','{"stem":"dispel 的意思是:","options":["加强","驱散,消除","聚集","制造"],"answer_index":1,"explanation_cn":"dispel = 驱散、消除。✓ dispel any further doubts."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',10,NULL,'choice','{"stem":"\"If you ___ to ask Harry, he would say it was mud.\"(虚拟对将来的假设:If + 主语 + ___ + to do)","options":["was","will","were","are"],"answer_index":2,"stem_cn":"如果你去问哈里,他会说那是泥。","explanation_cn":"虚拟对将来的假设,if 从句用 were to do。✓ If you were to ask Harry, … ✗ are / was / will。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',10,NULL,'choice','{"stem":"\"___ entering a store, he would invent a fancy name.\"(“一…就…”,填介词)","options":["On","In","At","By"],"answer_index":0,"stem_cn":"一进店,他就会当场编个名字。","explanation_cn":"On + 动名词,“一…就…”。✓ On entering a store, … ✗ In / At / By。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',10,NULL,'choice','{"stem":"\"keep a straight face\" 的意思是:","options":["转过脸去","面带微笑","抬起头来","板着脸、忍住不笑"],"answer_index":3,"explanation_cn":"keep a straight face = 板着脸、忍住不笑。✓ keep a straight face during the prank."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',10,NULL,'choice','{"stem":"\"out of stock\" 的意思是:","options":["脱销、没货了","免费赠送","存货充足","打折出售"],"answer_index":0,"explanation_cn":"out of stock = 脱销、没货了。✓ temporarily out of stock."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',10,NULL,'choice','{"stem":"What made Harry''s little game finally backfire?","options":["A clerk exposed him publicly","The store banned him","He forgot the fake name he used","He asked for ''perfumed mud'' as a joke, but the store really had it"],"answer_index":3,"passage":"My cousin Harry keeps a large, curiously shaped bottle on permanent display in his study. Despite the fact that the bottle is tinted a delicate shade of green, an observant visitor would soon notice that it is filled with what looks like a thick, grayish substance. If you were to ask Harry what was in the bottle, he would tell you that it contained perfumed mud. If you expressed doubt or surprise, he would immediately invite you to smell it and then to rub some into your skin. This brief experiment would dispel any further doubts you might have. The bottle really does contain perfumed mud. How Harry came into the possession of this outlandish stuff makes an interesting story, which he is fond of telling. What''s more, the acquisition of this bottle cured him of a bad habit he had been developing for years. Harry used to consider it a great joke to walk into expensive cosmetic stores and make outrageous requests for goods that do not exist. He would invent fanciful names on the spot. On entering a store, he would ask for a new perfume called ''Scented Shadow'' or for ''insoluble bath cubes.'' If a salesclerk told him she had never heard of it, he would pretend to be considerably put out. He loved to be told that one of his imaginary products was temporarily out of stock, and he would faithfully promise to come back at some future date — but of course he never did. How Harry managed to keep a straight face during these performances is quite beyond me. Harry does not need to be prompted to explain how he bought his precious bottle of mud. One day, he walked into an exclusive store downtown and asked for ''Myrolite.'' The salesclerk looked puzzled, and Harry repeated the word, slowly stressing each syllable. When the woman shook her head in bewilderment, Harry went on to explain that ''myrolite'' was a hard, amber-like substance that could be used to remove freckles. This explanation evidently meant something to the woman, who searched shelf after shelf. She produced all sorts of weird concoctions, but none of them met Harry''s requirements. When Harry put on his act of being mildly annoyed, the clerk promised to order some for him. Intoxicated by his success, Harry then asked for perfumed mud. He expected the clerk to look at him in blank astonishment. However, it was his turn to be surprised, for the woman''s eyes immediately lit up and she fetched several bottles, which she placed on the counter for Harry to inspect. For once, Harry had to admit defeat. He picked up what seemed to be the smallest bottle and discreetly asked the price. He was glad to get away with a mere twenty dollars, and he beat a hasty retreat, clutching the precious bottle under his arm. From then on, Harry decided that this little game he had invented might prove to be expensive. The curious bottle, which now adorns the bookcase in his study, was his first and last purchase of rare cosmetics.","explanation_cn":"课文说他把索要香水泥当玩笑,不料商店真有货,只好破费买下,这让他的把戏适得其反。✓ the store really had it."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',10,NULL,'choice','{"stem":"How did Harry usually behave when a clerk had never heard of his product?","options":["He would pretend to be considerably put out","He would buy something else","He would apologize","He would laugh and leave"],"answer_index":0,"passage":"My cousin Harry keeps a large, curiously shaped bottle on permanent display in his study. Despite the fact that the bottle is tinted a delicate shade of green, an observant visitor would soon notice that it is filled with what looks like a thick, grayish substance. If you were to ask Harry what was in the bottle, he would tell you that it contained perfumed mud. If you expressed doubt or surprise, he would immediately invite you to smell it and then to rub some into your skin. This brief experiment would dispel any further doubts you might have. The bottle really does contain perfumed mud. How Harry came into the possession of this outlandish stuff makes an interesting story, which he is fond of telling. What''s more, the acquisition of this bottle cured him of a bad habit he had been developing for years. Harry used to consider it a great joke to walk into expensive cosmetic stores and make outrageous requests for goods that do not exist. He would invent fanciful names on the spot. On entering a store, he would ask for a new perfume called ''Scented Shadow'' or for ''insoluble bath cubes.'' If a salesclerk told him she had never heard of it, he would pretend to be considerably put out. He loved to be told that one of his imaginary products was temporarily out of stock, and he would faithfully promise to come back at some future date — but of course he never did. How Harry managed to keep a straight face during these performances is quite beyond me. Harry does not need to be prompted to explain how he bought his precious bottle of mud. One day, he walked into an exclusive store downtown and asked for ''Myrolite.'' The salesclerk looked puzzled, and Harry repeated the word, slowly stressing each syllable. When the woman shook her head in bewilderment, Harry went on to explain that ''myrolite'' was a hard, amber-like substance that could be used to remove freckles. This explanation evidently meant something to the woman, who searched shelf after shelf. She produced all sorts of weird concoctions, but none of them met Harry''s requirements. When Harry put on his act of being mildly annoyed, the clerk promised to order some for him. Intoxicated by his success, Harry then asked for perfumed mud. He expected the clerk to look at him in blank astonishment. However, it was his turn to be surprised, for the woman''s eyes immediately lit up and she fetched several bottles, which she placed on the counter for Harry to inspect. For once, Harry had to admit defeat. He picked up what seemed to be the smallest bottle and discreetly asked the price. He was glad to get away with a mere twenty dollars, and he beat a hasty retreat, clutching the precious bottle under his arm. From then on, Harry decided that this little game he had invented might prove to be expensive. The curious bottle, which now adorns the bookcase in his study, was his first and last purchase of rare cosmetics.","explanation_cn":"课文说店员说没听说过时,哈里就装出十分懊恼、不快的样子。✓ pretend to be put out."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',10,NULL,'choice','{"stem":"What is really inside the curious bottle in Harry''s study?","options":["Colored water","Perfumed mud","Bath cubes","Green perfume"],"answer_index":1,"audio":"My cousin Harry keeps a large, curiously shaped bottle on permanent display in his study. Despite the fact that the bottle is tinted a delicate shade of green, an observant visitor would soon notice that it is filled with what looks like a thick, grayish substance. If you were to ask Harry what was in the bottle, he would tell you that it contained perfumed mud. If you expressed doubt or surprise, he would immediately invite you to smell it and then to rub some into your skin. This brief experiment would dispel any further doubts you might have. The bottle really does contain perfumed mud. How Harry came into the possession of this outlandish stuff makes an interesting story, which he is fond of telling. What''s more, the acquisition of this bottle cured him of a bad habit he had been developing for years. Harry used to consider it a great joke to walk into expensive cosmetic stores and make outrageous requests for goods that do not exist. He would invent fanciful names on the spot. On entering a store, he would ask for a new perfume called ''Scented Shadow'' or for ''insoluble bath cubes.'' If a salesclerk told him she had never heard of it, he would pretend to be considerably put out. He loved to be told that one of his imaginary products was temporarily out of stock, and he would faithfully promise to come back at some future date — but of course he never did. How Harry managed to keep a straight face during these performances is quite beyond me. Harry does not need to be prompted to explain how he bought his precious bottle of mud. One day, he walked into an exclusive store downtown and asked for ''Myrolite.'' The salesclerk looked puzzled, and Harry repeated the word, slowly stressing each syllable. When the woman shook her head in bewilderment, Harry went on to explain that ''myrolite'' was a hard, amber-like substance that could be used to remove freckles. This explanation evidently meant something to the woman, who searched shelf after shelf. She produced all sorts of weird concoctions, but none of them met Harry''s requirements. When Harry put on his act of being mildly annoyed, the clerk promised to order some for him. Intoxicated by his success, Harry then asked for perfumed mud. He expected the clerk to look at him in blank astonishment. However, it was his turn to be surprised, for the woman''s eyes immediately lit up and she fetched several bottles, which she placed on the counter for Harry to inspect. For once, Harry had to admit defeat. He picked up what seemed to be the smallest bottle and discreetly asked the price. He was glad to get away with a mere twenty dollars, and he beat a hasty retreat, clutching the precious bottle under his arm. From then on, Harry decided that this little game he had invented might prove to be expensive. The curious bottle, which now adorns the bookcase in his study, was his first and last purchase of rare cosmetics.","explanation_cn":"课文说那只古怪瓶子里装的确实是香水泥。✓ perfumed mud."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l52',10,NULL,'choice','{"stem":"How much did Harry pay to get away with the bottle?","options":["Five dollars","Nothing at all","A hundred dollars","A mere twenty dollars"],"answer_index":3,"audio":"My cousin Harry keeps a large, curiously shaped bottle on permanent display in his study. Despite the fact that the bottle is tinted a delicate shade of green, an observant visitor would soon notice that it is filled with what looks like a thick, grayish substance. If you were to ask Harry what was in the bottle, he would tell you that it contained perfumed mud. If you expressed doubt or surprise, he would immediately invite you to smell it and then to rub some into your skin. This brief experiment would dispel any further doubts you might have. The bottle really does contain perfumed mud. How Harry came into the possession of this outlandish stuff makes an interesting story, which he is fond of telling. What''s more, the acquisition of this bottle cured him of a bad habit he had been developing for years. Harry used to consider it a great joke to walk into expensive cosmetic stores and make outrageous requests for goods that do not exist. He would invent fanciful names on the spot. On entering a store, he would ask for a new perfume called ''Scented Shadow'' or for ''insoluble bath cubes.'' If a salesclerk told him she had never heard of it, he would pretend to be considerably put out. He loved to be told that one of his imaginary products was temporarily out of stock, and he would faithfully promise to come back at some future date — but of course he never did. How Harry managed to keep a straight face during these performances is quite beyond me. Harry does not need to be prompted to explain how he bought his precious bottle of mud. One day, he walked into an exclusive store downtown and asked for ''Myrolite.'' The salesclerk looked puzzled, and Harry repeated the word, slowly stressing each syllable. When the woman shook her head in bewilderment, Harry went on to explain that ''myrolite'' was a hard, amber-like substance that could be used to remove freckles. This explanation evidently meant something to the woman, who searched shelf after shelf. She produced all sorts of weird concoctions, but none of them met Harry''s requirements. When Harry put on his act of being mildly annoyed, the clerk promised to order some for him. Intoxicated by his success, Harry then asked for perfumed mud. He expected the clerk to look at him in blank astonishment. However, it was his turn to be surprised, for the woman''s eyes immediately lit up and she fetched several bottles, which she placed on the counter for Harry to inspect. For once, Harry had to admit defeat. He picked up what seemed to be the smallest bottle and discreetly asked the price. He was glad to get away with a mere twenty dollars, and he beat a hasty retreat, clutching the precious bottle under his arm. From then on, Harry decided that this little game he had invented might prove to be expensive. The curious bottle, which now adorns the bookcase in his study, was his first and last purchase of rare cosmetics.","explanation_cn":"课文说哈里仅花二十美元就脱了身,夹着瓶子匆匆撤退。✓ a mere twenty dollars."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
